package checker

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync/atomic"
	"testing"
	"time"
)

type transportFunc func(*http.Request) (*http.Response, error)

func (f transportFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }
func response(r *http.Request, code int, body io.ReadCloser) *http.Response {
	return &http.Response{StatusCode: code, Header: make(http.Header), Body: body, Request: r}
}
func engine(t *testing.T, workers int, timeout time.Duration, transport transportFunc) *Checker {
	t.Helper()
	c, err := New(Config{Workers: workers, RequestTimeout: timeout, Client: &http.Client{Transport: transport}})
	if err != nil {
		t.Fatal(err)
	}
	return c
}

type trackedBody struct {
	io.Reader
	closes *atomic.Int64
}

func (b trackedBody) Close() error { b.closes.Add(1); return nil }

func TestConfiguration(t *testing.T) {
	for _, config := range []Config{{Workers: 0, RequestTimeout: time.Second}, {Workers: 9, RequestTimeout: time.Second}, {Workers: 1}} {
		if _, err := New(config); err == nil {
			t.Fatalf("accepted invalid config: %+v", config)
		}
	}
}

func TestResultsStatusSortingDuplicatesAndCleanup(t *testing.T) {
	var closed atomic.Int64
	c := engine(t, 3, time.Second, func(r *http.Request) (*http.Response, error) {
		status := 200
		if r.URL.Path == "/bad" {
			status = 503
		}
		return response(r, status, trackedBody{Reader: strings.NewReader("ok"), closes: &closed}), nil
	})
	urls := []string{"https://example.test/z", "https://example.test/bad", "https://example.test/a", "https://example.test/a"}
	got, err := c.Check(context.Background(), urls)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"https://example.test/a", "https://example.test/a", "https://example.test/bad", "https://example.test/z"}
	if len(got) != len(want) {
		t.Fatalf("results: %d; want %d", len(got), len(want))
	}
	for i, result := range got {
		if result.URL != want[i] {
			t.Fatalf("position %d: %q; want %q", i, result.URL, want[i])
		}
	}
	if got[2].StatusCode != 503 || got[2].Error != "" {
		t.Fatalf("HTTP failure must remain a status: %+v", got[2])
	}
	if closed.Load() != int64(len(urls)) {
		t.Fatalf("closed %d bodies; want %d", closed.Load(), len(urls))
	}
}

func TestWorkerBound(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	var active, maximum atomic.Int64
	entered := make(chan struct{}, 32)
	release := make(chan struct{})
	defer close(release)
	c := engine(t, 8, time.Second, func(r *http.Request) (*http.Response, error) {
		current := active.Add(1)
		defer active.Add(-1)
		for {
			old := maximum.Load()
			if current <= old || maximum.CompareAndSwap(old, current) {
				break
			}
		}
		entered <- struct{}{}
		select {
		case <-release:
		case <-r.Context().Done():
			return nil, r.Context().Err()
		}
		return response(r, 200, io.NopCloser(strings.NewReader("ok"))), nil
	})
	urls := make([]string, 24)
	for i := range urls {
		urls[i] = fmt.Sprintf("https://example.test/%02d", i)
	}
	type outcome struct {
		results []Result
		err     error
	}
	done := make(chan outcome, 1)
	go func() { results, err := c.Check(ctx, urls); done <- outcome{results, err} }()
	for i := 0; i < 8; i++ {
		select {
		case <-entered:
		case <-ctx.Done():
			t.Fatal("workers did not start:", ctx.Err())
		}
	}
	if active.Load() != 8 {
		t.Fatalf("active = %d; want 8", active.Load())
	}
	// Release all workers without relying on a sleep or scheduling order.
	for i := 0; i < 24; i++ {
		select {
		case release <- struct{}{}:
		case <-ctx.Done():
			t.Fatal("workers did not finish")
		}
	}
	select {
	case outcome := <-done:
		if outcome.err != nil || len(outcome.results) != 24 {
			t.Fatalf("results=%d error=%v", len(outcome.results), outcome.err)
		}
	case <-ctx.Done():
		t.Fatal("run did not complete")
	}
	if maximum.Load() > 8 {
		t.Fatalf("worker limit exceeded: %d", maximum.Load())
	}
	if active.Load() != 0 {
		t.Fatal("request remained active after Check returned")
	}
}

func TestCancellationStopsInFlightWork(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	started := make(chan struct{}, 8)
	var active atomic.Int64
	c := engine(t, 4, time.Minute, func(r *http.Request) (*http.Response, error) {
		active.Add(1)
		defer active.Add(-1)
		started <- struct{}{}
		<-r.Context().Done()
		return nil, r.Context().Err()
	})
	done := make(chan error, 1)
	go func() {
		_, err := c.Check(ctx, []string{"https://example.test/a", "https://example.test/b", "https://example.test/c", "https://example.test/d", "https://example.test/e"})
		done <- err
	}()
	for i := 0; i < 4; i++ {
		select {
		case <-started:
		case <-time.After(2 * time.Second):
			t.Fatal("request did not start")
		}
	}
	cancel()
	select {
	case err := <-done:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("error=%v", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("canceled run did not finish")
	}
	if active.Load() != 0 {
		t.Fatal("canceled requests still active")
	}
}

func TestPerRequestDeadlineIsAResult(t *testing.T) {
	c := engine(t, 1, 10*time.Millisecond, func(r *http.Request) (*http.Response, error) { <-r.Context().Done(); return nil, r.Context().Err() })
	results, err := c.Check(context.Background(), []string{"https://example.test/slow"})
	if err != nil || len(results) != 1 || !strings.Contains(results[0].Error, "deadline exceeded") {
		t.Fatalf("results=%+v error=%v", results, err)
	}
}

func TestValidateEverythingBeforeNetworkWork(t *testing.T) {
	var requests atomic.Int64
	c := engine(t, 2, time.Second, func(r *http.Request) (*http.Response, error) {
		requests.Add(1)
		return response(r, 200, io.NopCloser(strings.NewReader(""))), nil
	})
	for _, bad := range []string{"", "relative/path", "ftp://example.test/a", "https://user:secret@example.test", "https://example.test/#fragment"} {
		if _, err := c.Check(context.Background(), []string{"https://example.test/valid", bad}); err == nil {
			t.Fatalf("accepted %q", bad)
		}
	}
	if requests.Load() != 0 {
		t.Fatalf("started %d requests for invalid input", requests.Load())
	}
}

func TestEmptyAndAlreadyCanceled(t *testing.T) {
	c := engine(t, 1, time.Second, func(*http.Request) (*http.Response, error) {
		t.Error("unexpected request")
		return nil, errors.New("unexpected")
	})
	if got, err := c.Check(context.Background(), nil); err != nil || len(got) != 0 {
		t.Fatalf("got=%v err=%v", got, err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := c.Check(ctx, []string{"https://example.test"}); !errors.Is(err, context.Canceled) {
		t.Fatalf("error=%v", err)
	}
}

type brokenReader struct{}

func (brokenReader) Read([]byte) (int, error) { return 0, errors.New("broken stream") }
func TestBodyReadErrorStillCloses(t *testing.T) {
	var closed atomic.Int64
	c := engine(t, 1, time.Second, func(r *http.Request) (*http.Response, error) {
		return response(r, 200, trackedBody{Reader: brokenReader{}, closes: &closed}), nil
	})
	got, err := c.Check(context.Background(), []string{"https://example.test"})
	if err != nil || len(got) != 1 || !strings.Contains(got[0].Error, "broken stream") || closed.Load() != 1 {
		t.Fatalf("got=%v err=%v closed=%d", got, err, closed.Load())
	}
}

func TestTransportFailureIsAResult(t *testing.T) {
	c := engine(t, 1, time.Second, func(*http.Request) (*http.Response, error) { return nil, errors.New("network unavailable") })
	got, err := c.Check(context.Background(), []string{"https://example.test"})
	if err != nil || len(got) != 1 || !strings.Contains(got[0].Error, "network unavailable") {
		t.Fatalf("got=%v err=%v", got, err)
	}
}

func TestURLLimit(t *testing.T) {
	c := engine(t, 1, time.Second, func(*http.Request) (*http.Response, error) {
		t.Error("unexpected request")
		return nil, errors.New("unexpected")
	})
	if _, err := c.Check(context.Background(), make([]string, MaxURLs+1)); err == nil {
		t.Fatal("accepted too many URLs")
	}
}

// Package checker performs bounded, cancelable HTTP health checks.
package checker

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"sync"
	"time"
)

const MaxWorkers = 8
const MaxURLs = 1000

type Config struct {
	Workers        int
	RequestTimeout time.Duration
	Client         *http.Client
}

type Result struct {
	URL        string `json:"url"`
	StatusCode int    `json:"status_code"`
	Error      string `json:"error,omitempty"`
}

// Checker may be shared by callers. Do not mutate its client's configuration
// during a run; the client's transport must support concurrent use.
type Checker struct {
	workers int
	timeout time.Duration
	client  *http.Client
}

func New(config Config) (*Checker, error) {
	if config.Workers < 1 || config.Workers > MaxWorkers {
		return nil, fmt.Errorf("workers must be between 1 and %d", MaxWorkers)
	}
	if config.RequestTimeout <= 0 {
		return nil, fmt.Errorf("request timeout must be positive")
	}
	client := config.Client
	if client == nil {
		client = &http.Client{}
	}
	return &Checker{workers: config.Workers, timeout: config.RequestTimeout, client: client}, nil
}

// Check validates the entire input before making requests. With no run-level
// cancellation it returns one result per URL, including duplicates and failures.
// On cancellation it returns completed results plus ctx.Err(). Results are sorted
// by URL. Individual request failures belong to Result, not the returned error.
func (c *Checker) Check(ctx context.Context, urls []string) ([]Result, error) {
	if ctx == nil {
		return nil, fmt.Errorf("context must not be nil")
	}
	if len(urls) > MaxURLs {
		return nil, fmt.Errorf("at most %d URLs are supported", MaxURLs)
	}
	for i, raw := range urls {
		parsed, err := url.Parse(raw)
		if err != nil || parsed.Hostname() == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.User != nil || parsed.Fragment != "" {
			return nil, fmt.Errorf("URL %d must be an absolute HTTP(S) URL without credentials or a fragment", i+1)
		}
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	results := make([]Result, 0, len(urls))
	if len(urls) == 0 {
		return results, nil
	}
	jobs := make(chan string)
	completed := make(chan Result)
	var workers sync.WaitGroup
	count := min(c.workers, len(urls))
	for i := 0; i < count; i++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case raw, ok := <-jobs:
					if !ok {
						return
					}
					if ctx.Err() != nil {
						return
					}
					result := c.checkOne(ctx, raw)
					// The collector always drains this channel, even after cancellation.
					// This send therefore cannot strand a worker when the run is stopped.
					completed <- result
				}
			}
		}()
	}
	// A single producer owns closing jobs. It observes cancellation while sending.
	go func() {
		defer close(jobs)
		for _, raw := range urls {
			select {
			case <-ctx.Done():
				return
			case jobs <- raw:
			}
		}
	}()
	// Only this coordinator closes the result channel, after all senders exit.
	go func() { workers.Wait(); close(completed) }()
	for result := range completed {
		results = append(results, result)
	}
	sort.SliceStable(results, func(i, j int) bool { return results[i].URL < results[j].URL })
	return results, ctx.Err()
}

func (c *Checker) checkOne(parent context.Context, raw string) Result {
	result := Result{URL: raw}
	ctx, cancel := context.WithTimeout(parent, c.timeout)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, raw, nil)
	if err != nil {
		result.Error = err.Error()
		return result
	}
	response, err := c.client.Do(request)
	if err != nil {
		result.Error = err.Error()
		return result
	}
	defer response.Body.Close()
	result.StatusCode = response.StatusCode
	// Discard at most 4 KiB. A large or endless response must not dominate a run.
	// A small body read to EOF may allow connection reuse. A read failure remains
	// observable; a limit by itself does not claim the whole body was consumed.
	if _, err := io.Copy(io.Discard, io.LimitReader(response.Body, 4096)); err != nil {
		result.Error = fmt.Sprintf("read response: %v", err)
	}
	return result
}

package main

import (
	"bytes"
	"context"
	"strings"
	"testing"
)

func TestReadURLs(t *testing.T) {
	got, err := readURLs(strings.NewReader("# a comment\n\n https://example.test/a \nhttps://example.test/b\n"))
	if err != nil || len(got) != 2 || got[0] != "https://example.test/a" {
		t.Fatalf("got=%v err=%v", got, err)
	}
}
func TestReadURLsRejectsOversizedLine(t *testing.T) {
	if _, err := readURLs(strings.NewReader(strings.Repeat("a", 70*1024))); err == nil {
		t.Fatal("accepted an oversized input line")
	}
}
func TestReadURLsRejectsTooManyURLs(t *testing.T) {
	if _, err := readURLs(strings.NewReader(strings.Repeat("https://example.test\n", 1001))); err == nil {
		t.Fatal("accepted too many URLs")
	}
}
func TestCLIUsage(t *testing.T) {
	for _, args := range [][]string{nil, {"-workers", "0", "https://example.test"}, {"-total", "0s", "https://example.test"}, {"-unknown"}} {
		var out, diagnostics bytes.Buffer
		if code := run(context.Background(), args, strings.NewReader(""), &out, &diagnostics); code != 2 {
			t.Fatalf("args=%v code=%d", args, code)
		}
		if diagnostics.Len() == 0 {
			t.Fatal("invalid usage must have diagnostics")
		}
	}
}
func TestHelp(t *testing.T) {
	var out, diagnostics bytes.Buffer
	if code := run(context.Background(), []string{"-help"}, strings.NewReader(""), &out, &diagnostics); code != 0 {
		t.Fatalf("code=%d", code)
	}
	if !strings.Contains(diagnostics.String(), "workers") {
		t.Fatal("help did not explain workers")
	}
}
func TestCanceledRunReportsFailure(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	var out, diagnostics bytes.Buffer
	if code := run(ctx, []string{"https://example.test"}, strings.NewReader(""), &out, &diagnostics); code != 1 {
		t.Fatalf("code=%d", code)
	}
	if !strings.Contains(diagnostics.String(), "canceled") {
		t.Fatalf("diagnostics=%q", diagnostics.String())
	}
}

package main

import (
	"bufio"
	"context"
	"encoding/json"
	"example.com/sitecheck/checker"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"strings"
	"time"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()
	code := run(ctx, os.Args[1:], os.Stdin, os.Stdout, os.Stderr)
	stop() // os.Exit does not run defers; release signal ownership explicitly.
	os.Exit(code)
}

func run(parent context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("sitecheck", flag.ContinueOnError)
	flags.SetOutput(stderr)
	workers := flags.Int("workers", 8, "maximum concurrent requests (1-8)")
	perRequest := flags.Duration("timeout", 2*time.Second, "deadline per request")
	total := flags.Duration("total", 15*time.Second, "deadline for the network checking stage")
	file := flags.String("file", "", "read URLs from a file, or - for stdin")
	asJSON := flags.Bool("json", false, "write a JSON result array")
	if err := flags.Parse(args); err != nil {
		if err == flag.ErrHelp {
			return 0
		}
		return 2
	}
	if *total <= 0 {
		fmt.Fprintln(stderr, "total deadline must be positive")
		return 2
	}
	engine, err := checker.New(checker.Config{Workers: *workers, RequestTimeout: *perRequest})
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	urls := flags.Args()
	if *file != "" {
		var input io.Reader = stdin
		if *file != "-" {
			opened, err := os.Open(*file)
			if err != nil {
				fmt.Fprintln(stderr, err)
				return 2
			}
			defer opened.Close()
			input = opened
		}
		added, err := readURLs(input)
		if err != nil {
			fmt.Fprintln(stderr, err)
			return 2
		}
		urls = append(urls, added...)
	}
	if len(urls) == 0 {
		fmt.Fprintln(stderr, "provide URLs as arguments or with -file")
		return 2
	}
	ctx, cancel := context.WithTimeout(parent, *total)
	defer cancel()
	results, runError := engine.Check(ctx, urls)
	var outputError error
	if *asJSON {
		outputError = json.NewEncoder(stdout).Encode(results)
	} else {
		for _, result := range results {
			status := fmt.Sprint(result.StatusCode)
			if result.Error != "" {
				status = "ERROR"
			}
			if _, err := fmt.Fprintf(stdout, "%s\t%s\n", status, result.URL); err != nil {
				outputError = err
				break
			}
			if result.Error != "" {
				fmt.Fprintf(stderr, "%s: %s\n", result.URL, result.Error)
			}
		}
	}
	if outputError != nil {
		fmt.Fprintln(stderr, "write report:", outputError)
		return 1
	}
	if runError != nil {
		fmt.Fprintln(stderr, "check:", runError)
		return 1
	}
	for _, result := range results {
		if result.Error != "" || result.StatusCode < 200 || result.StatusCode >= 300 {
			return 1
		}
	}
	return 0
}

func readURLs(input io.Reader) ([]string, error) {
	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 1024), 64*1024)
	urls := make([]string, 0)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if len(urls) >= checker.MaxURLs {
			return nil, fmt.Errorf("input exceeds %d URLs", checker.MaxURLs)
		}
		urls = append(urls, line)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("read URL list: %w", err)
	}
	return urls, nil
}
